reasons=[
[(['generous','stingy','frugal','rich','wasteful'],'Задан именно имущественный смысл щедрости. Из четырёх прилагательных только скупой выражает противоположную установку; остальные обозначают экономию, достаток и неразумные траты.'),(['stingy','frugal'],'Объяснение точно различает нейтральную экономность и чрезмерность до жадности; смысл не расширен до всех значений слов.'),(['stingy'],'Заметка верна и даёт новый факт — сдержанность в похвалах/словах, отсутствующий в prompt/key.'),(['frugal','stingy'],'Заметка раскрывает экономность и конкретно отделяет её от жадности.'),(['rich'],'Достаток не определяет готовность делиться; заметка устраняет имущественную ассоциацию.'),(['wasteful','generous'],'Неумеренное расходование не является противоположностью готовности делиться. Заметка верно разделяет признаки; статья щедрый допускает щедрость до расточительства.')],
[(['sleeve','secretive','slow'],'Ключ 1 верен, все четыре ответа наречные характеристики выполнения работы. Однако третий ответ обоснован заметкой через нерелевантное первое значение скрытный.'),(['sleeve'],'Оба толкования верны. Слова «противопоставлена пара» — редакционное сопоставление соседних выражений, не буквальная метка антонимии словаря. Объяснение прямо сообщает ответ CURRENT-соседа sleeves-rolled.'),(['sleeve'],'Толкование засучив рукава подтверждено. Заметка полезно исключает 0, но воспроизводит целевой факт другой карточки.'),(['sleeve'],'Буквальное значение рукава верно и добавляет факт за пределами ключа, без выдуманной этимологии.'),(['secretive'],'FIX: вариант описывает скрытность самого действия, а заметка выбирает черту человека и не объясняет «чтобы никто не видел». Полная статья даёт именно нужное второе значение и наречные примеры; нельзя утверждать, будто это только характеристика человека.'),(['slow','sleeve'],'Темп и старание различаются; заметка полезна и подтверждена двумя значениями медлительный.')],
[(['puton','dress','dressself','shoe'],'Ключ 3 единственный нейтрально нормативный. Однако «он должен одеться пальто» синтаксически дефектно по возвратности/управлению; «обуть пальто» — семантически далёкий отвлекающий вариант. Условия четырёх грамматичных, сопоставимо правдоподобных подстановок не выполнены.'),(['puton','dress','dressself'],'В заданном контексте объяснение верно; не следует трактовать первую фразу как всеобщее правило для любых неодушевлённых объектов. Одеть имеет также переносные значения, прочитанные целиком.'),(['dress'],'Малыш и кукла действительно примеры; заметка объясняет ошибку одеть пальто через объект действия.'),(['dressself','puton'],'Содержательный вывод верен: возвратная конструкция не принимает прямое дополнение пальто. Но авторская ссылка только на ОДЕТЬ не является прямой нормой про ОДЕТЬСЯ; читатель проверил соседнюю статью отдельно. Сам вариант остаётся грамматической подсказкой.'),(['shoe'],'Обувь, валенки, туфли подтверждены; note полезно исключает пальто, но сам distractor слабее основной паронимической пары.'),(['puton'],'Оба предметных примера подтверждены значением 1; note добавляет полезный факт об употреблении за пределами одежды. В оригинале порядок «на дверь цепочку», пересказ допустим.')]]
subs=[
[('Слово «скупой» противоположно слову «щедрый» в указанном значении.','Грамматично, мужской род единственного числа; единственный ключ, точное противопоставление.'),('Слово «бережливый» противоположно слову «щедрый» в указанном значении.','Грамматично; убедительная близкая ошибка из смешения экономности и жадности.'),('Слово «богатый» противоположно слову «щедрый» в указанном значении.','Грамматично; имущественная ассоциация правдоподобна на easy, но это другой признак.'),('Слово «расточительный» противоположно слову «щедрый» в указанном значении.','Грамматично; тематически близкая оценка траты, ошибочный антоним.')],
[('Работу делают усердно, старательно и энергично.','Грамматично и параллельно; правдоподобная путаница двух образных выражений.'),('Работу делают небрежно, кое-как.','Грамматично; единственный ключ по полному фразеологическому контексту.'),('Работу делают скрытно, чтобы никто не видел.','Грамматично; возможный способ выполнения, но с образом рукава связан слабо; note использует не тот смысл.'),('Работу делают медленно и размеренно.','Грамматично; правдоподобное смешение отсутствия старания и медленного темпа.')],
[('Перед выходом он должен одеть пальто.','Синтаксическая рамка переходного инфинитива сохранена; неверный выбор паронима, сильный distractor.'),('Перед выходом он должен одеться пальто.','FIX: нет управления прямым дополнением пальто у возвратного одеться. Отдельная грамматическая ошибка облегчает исключение, не проверяя основной выбор одеть/надеть.'),('Перед выходом он должен обуть пальто.','Формально переходная рамка сохранена, семантическая сочетаемость нарушена очевидно: обувь/пальто; слабый distractor.'),('Перед выходом он должен надеть пальто.','Нормативно, естественно; словарь даёт точный объект пальто.')]]
